L += ['', '## สุขภัณฑ์ทีละจุด', '', '| รหัส | ชนิด | ห้อง | ระดับอ้างอิง z | ตำแหน่ง | หันหน้า | สถานะ |', '|---|---|---|---|---|---|---|']
for f in pl['fixtures']: L.append(f"| {f['id']} | {f['type']} | {f['room']} | +{f['xyz'][2]:.2f} | {gp(f['xyz'][0], f['xyz'][1])} | {({0: 'ไปทางกริด 4', 180: 'ไปทางกริด 1', 90: 'ไปทางแถว C', -90: 'ไปทางแถว A'}.get(f.get('rot'), '—'))} | {f['status']} |")
L += ['', '## อุปกรณ์', '', '| รหัส | รายการ | ตำแหน่ง | หมายเหตุ |', '|---|---|---|---|']
for e in pl['equipment']: L.append(f"| {e['id']} | {e['kind']} {e['size']} | {gp(e['xyz'][0], e['xyz'][1])} | {e.get('note', '')} |")
